// Guide helper functions (must be defined before apGuides uses them)
function makeChapter(num, title, sections) {
  return { num, title, sections };
}
function concepts(items) { return { type:'concepts', items }; }
function vocab(items)    { return { type:'vocab',    items }; }
function tips(items)     { return { type:'tips',     items }; }
function frq(items)      { return { type:'frq',      items }; }
function quiz(items)     { return { type:'quiz',     items }; }
