apGuides.aplit = {
  title: 'AP English Literature & Composition',
  exam: 'May 2026 · 3 hrs · MCQ + Poetry Analysis + Prose Analysis + Literary Argument',
  passRate: '72.4%',
  chapters: [
    makeChapter(1,'Poetry Analysis',[
      concepts([
        { term:'Poetic Form & Structure', body:'Sonnet (14 lines: Petrarchan = octave+sestet; Shakespearean = 3 quatrains+couplet). Ode: elevated praise of a subject. Elegy: lament for the dead. Free verse: no regular rhyme/meter. Villanelle: two refrains, 19 lines.' },
        { term:'Sound Devices', body:'Rhyme scheme (ABAB, ABCABC). Meter: iambic pentameter (5 iambs per line: da-DUM × 5). Alliteration (consonant repetition at word start). Assonance (vowel repetition). Consonance (consonant repetition). Onomatopoeia. These create rhythm, emphasis, and emotion.' },
        { term:'Figurative Language in Poetry', body:'Metaphor, simile (like/as), personification (human traits to non-human), apostrophe (address to absent/non-human entity), synesthesia (mixing senses), extended metaphor (sustained throughout poem), conceit (elaborate, unusual metaphor, common in Metaphysical poetry).' },
        { term:'Poetic Voice & Tone', body:'Speaker (not the author). Tone: attitude revealed through word choice. Irony: verbal (says opposite of meaning), situational (event is opposite of expectation), dramatic (audience knows more than characters). Shift: change in tone or perspective — mark with a volta (turn in sonnets at line 9 or 13).' },
      ]),
      vocab([
        { term:'Volta', def:'The "turn" in a sonnet — a shift in argument, perspective, or tone. In Petrarchan sonnets at line 9; in Shakespearean at the couplet.' },
        { term:'Enjambment', def:'A line that continues to the next without a natural pause — creates momentum, ambiguity, or suspense.' },
        { term:'Caesura', def:'A pause within a line (often shown with punctuation) — creates rhythm variation and emphasis.' },
        { term:'Extended metaphor', def:'A comparison that runs through multiple lines or the entire poem, developing a central analogy.' },
      ]),
      tips(['Read every poem multiple times: first for meaning, then for tone, then for devices.','The speaker is not the author. Never say "Keats feels..." — say "the speaker..."','A shift (volta) in a poem is one of the most important things to identify and analyze.']),
      frq(['FRQ poetry essay: identify the central subject → analyze HOW the poet uses language/structure to develop that subject → connect devices to meaning, not just list them.']),
      quiz([
        { q:"Iambic pentameter consists of:", opts:["5 trochees per line","5 iambs per line (da-DUM pattern, 10 syllables)","4 iambs per line","Free verse with 10 syllables"], ans:1, exp:"Iambic pentameter: iamb = unstressed + STRESSED syllable (da-DUM). Pentameter = 5 feet per line. 5 iambs = 10 syllables. Shakespeare's default meter. 'Shall I comPARE thee TO a SUM mer's DAY?'" },
        { q:"Apostrophe as a literary device means:", opts:["A punctuation mark","Addressing a dead person, absent person, or personified object directly — 'O Death, where is thy sting?'","A simile using 'like'","Repetition of a phrase"], ans:1, exp:"Apostrophe: direct address to someone/something that isn't present or can't respond. Common in poetry: addressing death, nature, abstract concepts. Creates emotional intensity and intimacy." },
        { q:"The 'volta' in a Petrarchan sonnet typically occurs at:", opts:["Line 7","Line 9 — the shift from octave to sestet","Line 14 — the final couplet","Line 4"], ans:1, exp:"Petrarchan (Italian) sonnet: 8-line octave presents a problem/question; 9th line begins the sestet with a shift (volta) in perspective, resolution, or counter-argument." },
        { q:"Enjambment in poetry creates:", opts:["A pause within a line","A line that flows without pause into the next line, creating momentum or ambiguity","A regular rhyme scheme","End-stopped lines"], ans:1, exp:"Enjambment: the meaning runs over the line break. Often used to withhold information (the reader must read on), create speed, or emphasize the word at the beginning of the new line." },
        { q:"A villanelle's defining formal features are:", opts:["14 lines with a rhyming couplet","Two repeating refrains and a specific rhyme scheme (ABA) across 19 lines","8 lines of iambic pentameter","6 stanzas of 4 lines each"], ans:1, exp:"Villanelle: 19 lines, 5 tercets (3-line stanzas) + 1 quatrain. First and third lines of the first stanza repeat alternately as final lines of subsequent stanzas, then together as final couplet. Dylan Thomas's 'Do Not Go Gentle...' is the classic example." },
        { q:"Synesthesia in poetry refers to:", opts:["Comparing two unlike things","Mixing sensory descriptions — describing sound in visual terms or taste in tactile terms, etc.","Repetition of consonant sounds","A pause in the middle of a line"], ans:1, exp:"Synesthesia: 'loud colors,' 'a sharp smell,' 'soft sounds.' Blending senses creates vivid, unexpected imagery that forces the reader to experience the subject in a new way." },
        { q:"In AP Lit poetry analysis, when you identify a metaphor, the next required step is:", opts:["Name the two things being compared","Explain the EFFECT of the comparison on the reader's understanding of the poem's subject","Count how many metaphors appear","Identify whether it is an extended metaphor"], ans:1, exp:"AP Lit scoring: device identification = 0 analysis points. Explaining the rhetorical/thematic effect of the device on the reader = analysis credit. Always ask 'so what does this comparison make the reader understand/feel?'" },
        { q:"Which statement about AP Lit poetry essays is correct?", opts:["The essay should summarize the poem's content","The essay should analyze how poetic choices contribute to the poem's meaning — not summarize","The essay must identify every literary device in the poem","The essay should focus only on figurative language"], ans:1, exp:"AP Lit essays analyze meaning through form. You need: a defensible thesis about the poem's meaning → body paragraphs linking specific poetic choices to that meaning → analysis of effect." },
        { q:"Alliteration differs from assonance in that:", opts:["Alliteration is vowel repetition; assonance is consonant repetition","Alliteration is repetition of INITIAL CONSONANT sounds; assonance is repetition of VOWEL sounds","They are the same device","Alliteration applies only to words in the same line"], ans:1, exp:"Alliteration: initial consonant sounds repeated ('Peter Piper picked...'). Assonance: internal vowel sounds repeated ('The rain in Spain stays mainly...'). Both create rhythm and sonic texture." },
        { q:"Dramatic irony in poetry or fiction means:", opts:["The speaker says the opposite of what they mean","The audience/reader knows something that a character or speaker does not","An event turns out opposite to expectations","The author directly contradicts a character"], ans:1, exp:"Dramatic irony: a gap in knowledge between the reader and a character. Classic example: Oedipus doesn't know he killed his father; the audience does. Creates tension, pathos, or horror." }
      ])
    ]),
    makeChapter(2,'Prose Fiction Analysis',[
      concepts([
        { term:'Narrative Point of View', body:'First person (I/we): intimate, limited to narrator\'s knowledge, possibly unreliable. Second person (you): unusual, immersive. Third person limited: outside narrator, one character\'s perspective. Third person omniscient: outside narrator knows all characters\' thoughts.' },
        { term:'Characterization', body:'Direct: narrator tells you ("She was kind"). Indirect (STEAL): Speech, Thought, Effect on others, Actions, Looks. Round characters: complex, dynamic, change. Flat: one-dimensional, static. Foil: character who contrasts with another to highlight their traits.' },
        { term:'Setting & Atmosphere', body:'Setting includes time, place, and social environment. Atmosphere (mood): the emotional feeling evoked. Setting can function as a character, a symbol, or a controlling metaphor. Pathetic fallacy: nature reflects characters\' emotions (storm = turmoil).' },
        { term:'Narrative Techniques', body:'In medias res: starting in the middle of action. Flashback/analepsis. Foreshadowing: hints at future events. Stream of consciousness: unfiltered thought flow. Free indirect discourse: third-person narration that adopts the character\'s voice/viewpoint.' },
      ]),
      vocab([
        { term:'Unreliable narrator', def:'A narrator whose account cannot be fully trusted — due to limited information, self-interest, mental state, or youth (e.g., Holden Caulfield, Stevens in The Remains of the Day).' },
        { term:'Foil', def:'A character who contrasts with another (usually the protagonist) to highlight specific traits. Laertes is Hamlet\'s foil (decisive action vs. Hamlet\'s paralysis).' },
        { term:'Free indirect discourse', def:'A blend of third-person narration and character thought — no dialogue tag, but the narrative takes on the character\'s voice and perspective. Common in Jane Austen.' },
      ]),
      tips(['When analyzing prose, ask: what is the effect of the NARRATOR\'s choice to reveal this information at this moment in this way?','Character foils: always ask what the contrast illuminates about the protagonist\'s defining qualities.','Setting is never just background in literary fiction — always ask what function it serves.']),
      frq(['FRQ prose analysis: choose ONE lens (characterization, setting, narrative voice) and develop a sustained argument about how it serves the work\'s overall meaning.']),
      quiz([
        { q:"An unreliable narrator is one who:", opts:["Always tells the truth","Cannot be fully trusted — due to self-interest, limited knowledge, mental state, or age","Is not the main character","Speaks in first person"], ans:1, exp:"Unreliable narrator: the reader must read between the lines. Examples: the governess in 'The Turn of the Screw' (possibly hallucinating), Humbert Humbert in 'Lolita' (self-justifying), Nick Carraway in Gatsby (naively admiring)." },
        { q:"Free indirect discourse is a technique where:", opts:["A character speaks directly in dialogue","Third-person narration adopts the character's voice, thoughts, and syntax without quotation marks","The author directly addresses the reader","Stream of consciousness flows without punctuation"], ans:1, exp:"Free indirect discourse: 'She was so happy. She could have cried.' The narrator isn't quoting the character but speaking with their emotional coloring. Jane Austen and Flaubert mastered this technique." },
        { q:"A foil character primarily serves to:", opts:["Replace the protagonist","Contrast with another character to highlight that character's defining traits","Provide comic relief","Represent the antagonist"], ans:1, exp:"Foil: by contrasting with the protagonist, a foil makes the protagonist's traits more vivid. Laertes (decisive, passionate) foils Hamlet (hesitant, philosophical). The contrast defines both characters." },
        { q:"Pathetic fallacy refers to:", opts:["A factual error in the plot","Using nature/environment to reflect or symbolize a character's emotional state (storm = inner turmoil)","An unreliable narrator","Dialogue that doesn't match a character's personality"], ans:1, exp:"Pathetic fallacy (John Ruskin's term): attributing human emotions to nature. The pathetic fallacy in Wuthering Heights: wild moors mirror Heathcliff's savage passion. In Lear: the storm mirrors Lear's madness." },
        { q:"In medias res means a narrative begins:", opts:["At the story's beginning chronologically","In the middle of the action, then fills in backstory","At the story's end","With an unreliable narrator"], ans:1, exp:"In medias res ('into the middle of things'): The Iliad opens during the 10th year of the Trojan War, not at the beginning. Forces the reader to piece together context. Creates immediate dramatic engagement." },
        { q:"Third-person omniscient narration differs from third-person limited in that:", opts:["Third-person limited uses 'I'","Omniscient can access all characters' thoughts; limited stays with one character's perspective","Limited has no access to any character's thoughts","Omniscient is always unreliable"], ans:1, exp:"Omniscient: the narrator can enter any character's mind, knows all, and can move between perspectives. Limited: the narrator follows one character's perspective, creating more intimacy and restriction." },
        { q:"When analyzing a passage's diction, you should focus on:", opts:["The total number of words","Specific word choices and their connotations — why THESE words rather than synonyms","Only the longest words","The sentence length"], ans:1, exp:"Diction analysis: ask WHY specific words are chosen. 'Staggered' vs 'walked' creates a completely different impression. Connotation, register (formal/informal), and specificity all contribute to meaning." },
        { q:"The AP Lit prose analysis essay asks you to analyze a passage and then:", opts:["Summarize the plot","Explain how the author's choices in the passage contribute to the work's overall meaning or effect","Identify every literary device","Compare it to another work"], ans:1, exp:"AP Lit prose FRQ: analyze HOW the author uses specific literary techniques and choices to contribute to the work's meaning or purpose. Not summarize. Not list devices. Analyze how and why." },
        { q:"Stream of consciousness as a narrative technique:", opts:["Tells the story chronologically with clear transitions","Presents a character's unfiltered, continuous thought flow — often without standard grammar or chronological order","Uses a third-person omniscient narrator","Focuses exclusively on external action"], ans:1, exp:"Stream of consciousness: Virginia Woolf, James Joyce, Faulkner. Captures the associative, fragmented nature of thought. 'Mrs. Dalloway' and 'Ulysses' are canonical examples. Immerses reader in subjective experience." },
        { q:"Setting in serious literary fiction typically functions as:", opts:["Merely background context","A meaningful element that reflects character psychology, controls theme, or acts as a symbol","A distraction from character development","Only historical context"], ans:1, exp:"Setting as meaning: the fog in 'Bleak House' (moral obscurity in the legal system), the decaying mansion in 'Great Expectations' (illusions, past), the green light in 'Gatsby' (the unreachable dream). Setting is never just backdrop." }
      ])
    ]),
    makeChapter(3,'Drama Analysis',[
      concepts([
        { term:'Dramatic Elements', body:'Plot: exposition → rising action → climax → falling action → resolution. Tragic structure: hamartia (fatal flaw) → hubris → nemesis → catharsis. Dramatic irony, soliloquy (alone, reveals inner thought), aside (speaks to audience, unheard by others), stage direction.' },
        { term:'Shakespearean Conventions', body:'Soliloquies reveal true inner state (vs. performance for other characters). Comedies end in marriage; tragedies end in death. Villains often have the best poetry (Iago, Edmund). Disguise reveals truth. The play-within-a-play tests reactions.' },
        { term:'Modern Drama', body:'Realism: everyday characters, authentic dialogue, social issues (Ibsen, Chekhov, Miller). Absurdism: meaningless waiting, breakdown of logic and language (Beckett\'s Waiting for Godot). Expressionism: distorted reality to show inner psychological states.' },
      ]),
      tips(['In Shakespeare, analyze the verse — when a character shifts from prose to poetry or vice versa, it signals something about their social status or emotional state.','Tragic hamartia: specific to the character, not a general flaw. Hamlet\'s is excessive thought/paralysis; Macbeth\'s is unchecked ambition.','The ending of a tragedy provides catharsis — emotional purging for the audience through pity and fear.']),
      quiz([
        { q:"Hamartia in classical tragedy refers to:", opts:["The resolution of the plot","The protagonist's fatal flaw or error that leads to their downfall","The moment of greatest tension","The antagonist's motivation"], ans:1, exp:"Hamartia (Aristotle): the fatal flaw or error of judgment that sets the tragic hero on a path to destruction. Oedipus's hamartia = excessive desire to know the truth; Macbeth's = unchecked ambition fueled by self-deception." },
        { q:"A dramatic soliloquy serves to:", opts:["Allow characters to speak to each other","Reveal a character's innermost thoughts directly to the audience — as if thinking aloud","Advance the plot quickly","Introduce new characters"], ans:1, exp:"Soliloquy: character alone (or acting as if alone), speaks thoughts directly to audience. Hamlet's 'To be or not to be' gives us his psychological state in real time. The character is not performing for other characters." },
        { q:"Catharsis at the end of a Greek tragedy produces:", opts:["Anger and frustration in the audience","Emotional purging — the audience experiences pity and fear, then emotional release and clarity","A desire for revenge","Confusion about the moral lesson"], ans:1, exp:"Catharsis (Aristotle): watching tragedy produces pity (for the hero) and fear (identifying with the hero's vulnerability). The emotional purging at the end leaves the audience cleansed and with heightened moral awareness." },
        { q:"Samuel Beckett's 'Waiting for Godot' is associated with:", opts:["Greek tragedy","Realism","Absurdism — characters wait pointlessly, language breaks down, nothing happens and nothing means anything","Shakespearean romance"], ans:2, exp:"Absurdism: the universe is meaningless and human efforts to find meaning are futile. Beckett's characters wait forever for 'Godot' who never comes — a metaphor for waiting for meaning or salvation that doesn't arrive." },
        { q:"When Shakespeare's characters switch from blank verse to prose, it typically signals:", opts:["The end of the play","Lower-class characters speaking or a character in a mentally destabilized state","A more formal occasion","The author's personal voice"], ans:1, exp:"Shakespeare's register shift: nobles speak blank verse (iambic pentameter); commoners and clowns speak prose. When a noble shifts to prose, it often signals mental breakdown (Lear's madness), comedy, or intimacy." },
        { q:"Dramatic irony in theater means:", opts:["Characters say the opposite of what they mean","The audience knows something a character doesn't — creating tension, horror, or pathos","Two characters have opposite personalities","The plot ends in an unexpected way"], ans:1, exp:"Dramatic irony: Oedipus investigates his father's murder — the audience knows he IS the murderer. Romeo thinks Juliet is dead — we know she'll wake. The gap between what characters know and what we know creates the dramatic tension." },
        { q:"The 'play within a play' in Hamlet (The Mousetrap) serves to:", opts:["Entertain the court","Test Claudius's guilt by staging a re-enactment of his crime — Hamlet will observe his reaction","Introduce new characters","Provide comic relief"], ans:1, exp:"The Mousetrap: 'The play's the thing / Wherein I'll catch the conscience of the king.' Hamlet uses theater to confirm Claudius's guilt through his involuntary reaction — meta-theatrical examination of performance vs. truth." },
        { q:"An aside in drama is:", opts:["A long speech by a character alone on stage","A brief remark spoken to the audience that other characters supposedly cannot hear","Stage directions in the text","A conversation between two characters"], ans:1, exp:"Aside: a character speaks briefly to the audience (or themselves) while other characters are present but conventionally can't hear. Creates theatrical complicity between character and audience." },
        { q:"Ibsen's realistic plays (like 'A Doll's House') differ from earlier drama by:", opts:["Using supernatural elements","Focusing on ordinary middle-class characters facing real social problems in authentic dialogue","Using Greek chorus","Being written in verse"], ans:1, exp:"Ibsenian realism: moved theater away from classical heroes and artificial language toward ordinary people, naturalistic dialogue, and real social issues (women's rights, class hypocrisy, personal freedom vs. social duty)." },
        { q:"Hubris in tragedy refers to:", opts:["The tragic hero's moment of self-recognition","Excessive pride or arrogance that leads to the downfall — the hero challenges the natural/divine order","The tragic hero's fatal flaw","The resolution of the conflict"], ans:1, exp:"Hubris: overweening pride that leads humans to challenge gods or fate. Oedipus's determination to discover truth despite warnings; Macbeth's belief he can transcend prophecy — hubris invites nemesis (divine retribution)." }
      ])
    ]),
    makeChapter(4,'Novel & Long Fiction',[
      concepts([
        { term:'Thematic Development', body:'Theme is not a topic (love, death) but a statement about human experience (Love destroys those who seek to possess another; Death forces the living to confront the meaning of their own lives). Themes develop through character, plot, imagery, and symbolism working together.' },
        { term:'Symbolism & Allegory', body:'Symbol: concrete object representing an abstract idea. Allegorical: narrative with a consistent parallel meaning (Orwell\'s "Animal Farm" = Soviet history; "Lord of the Flies" = innate human evil). Analyze symbols in context — what does this object/place mean SPECIFICALLY in this text?' },
        { term:'The Novel\'s Social Context', body:'Victorian: social mobility, class anxiety, industrialization (Dickens). Modernist: fragmented identity, loss of meaning post-WWI (Woolf, Joyce). Postmodern: metafiction, intertextuality, unreliable narrators, resistance to totalizing narratives.' },
      ]),
      tips(['AP Lit open essay: you choose the text. Know 3–4 works deeply — don\'t try to know 20 superficially.','Themes must be arguable statements. "The Great Gatsby is about the American Dream" is not a theme — it\'s a topic.','For every symbol you identify, prove it is a symbol with textual evidence: HOW does the author develop this object as a recurring, resonant image?']),
      quiz([
        { q:"A theme in literary analysis must be:", opts:["A one-word topic like 'love' or 'war'","An arguable statement about human experience that the work develops and explores","The plot summary","The author's biography"], ans:1, exp:"Theme: a statement, not a topic. 'Lord of the Flies' topic = civilization vs. savagery. Theme = 'Without social structures, humanity's innate capacity for violence inevitably emerges.' Must be an arguable claim the work proves." },
        { q:"Allegory differs from symbolism because:", opts:["Symbols appear only in poetry","Allegory is a sustained narrative where characters and events consistently represent something beyond the story (usually political/historical); symbolism is more local","Allegory uses only one symbol","Symbolism applies only to objects"], ans:1, exp:"Allegory: the ENTIRE narrative maps onto another meaning. 'Animal Farm' = USSR. 'Pilgrim's Progress' = Christian journey to salvation. Symbolism: specific objects/characters represent ideas but without a complete parallel narrative." },
        { q:"Postmodern fiction is characterized by:", opts:["Traditional linear narratives","Metafiction (fiction that comments on its own fictionality), unreliable narrators, intertextuality, and resistance to definitive interpretations","Social realism","Victorian social criticism"], ans:1, exp:"Postmodern features: self-conscious fictionality ('I am a character in a novel and I know it'), fragmented chronology, multiple competing truths, parody of earlier literary forms, and refusal of clear moral resolution." },
        { q:"In the AP Lit open essay (FRQ 3), your choice of text should be:", opts:["The most recent book you've read","A work of literary merit that you know deeply enough to develop a complex argument","Any book you enjoyed","A work from the AP Lit reading list only"], ans:1, exp:"Open essay: any work of recognized literary merit works. You earn no extra points for impressive titles — you earn points for complex, well-supported analysis. Know 3–4 texts deeply rather than many superficially." },
        { q:"The green light in 'The Great Gatsby' functions primarily as:", opts:["A traffic signal near Gatsby's house","A symbol of Gatsby's longing for Daisy and, more broadly, the unattainable American Dream","A literal lighthouse","A symbol of Daisy's wealth"], ans:1, exp:"Fitzgerald's green light: Gatsby reaches toward it across the bay — it represents desire, the impossibility of recovering the past, and the seductive but deceptive promise of the American Dream. Symbol analysis requires textual evidence of its development." },
        { q:"Unreliable narration in 'The Great Gatsby' (Nick Carraway) is significant because:", opts:["Nick tells a perfectly objective story","Nick's admiration for Gatsby and his own class anxieties color his account — readers must read critically and 'between the lines'","Nick is proven wrong about everything","Fitzgerald directly corrects Nick's errors"], ans:1, exp:"Nick's unreliability: he declares himself 'one of the few honest people' — while making multiple dishonest omissions and distortions. His admiration for Gatsby's dream clouds his judgment. We see through Nick to understand what he can't admit." },
        { q:"'Stream of consciousness' is associated most strongly with which literary movement?", opts:["Victorian realism","Modernism — particularly Virginia Woolf, James Joyce, and William Faulkner","The Harlem Renaissance","Absurdism"], ans:1, exp:"Modernist stream of consciousness: a response to the fragmented, subjective experience of post-WWI modernity. Woolf's 'Mrs. Dalloway,' Joyce's 'Ulysses,' and Faulkner's 'The Sound and the Fury' all use it to represent interior psychological reality." },
        { q:"The primary purpose of analyzing an author's sentence structure (syntax) in prose is:", opts:["To count sentence length","To understand HOW the pacing, complexity, or rhythm of sentences creates meaning or reveals character psychology","To improve your own writing","To identify grammatical errors"], ans:1, exp:"Syntax analysis: a character who thinks in long, subordinate-clause-filled sentences suggests a particular kind of consciousness. Short sentences at a moment of crisis create urgency. HOW someone speaks (or thinks) reveals WHO they are." },
        { q:"Dickens's critique of Victorian society in his novels most often targets:", opts:["The aristocracy exclusively","Class hypocrisy, the cruelty of industrialization, the failures of legal and charitable institutions, and the gap between moral rhetoric and social reality","Educational systems only","Personal morality without social dimension"], ans:1, exp:"Dickens's social criticism: Chancery Court (Bleak House), workhouses (Oliver Twist), industrial capitalism (Hard Times), debtors' prison (Little Dorrit). He targeted systemic failures that the Victorian middle class preferred to ignore." },
        { q:"When writing the AP Lit open essay (FRQ 3), you should spend the first 5 minutes:", opts:["Writing the introduction","Re-reading the prompt and thinking of the best text to use","Planning: deciding your thesis, the aspects of the work you'll analyze, and specific textual evidence","Writing your conclusion first"], ans:2, exp:"Open essay strategy: 5 minutes — choose text, form a specific arguable thesis about the work in relation to the prompt, identify 2–3 aspects of the work (scenes, characters, symbols) as evidence, plan body paragraph structure. Then write." }
      ])
    ]),
  ]
};

