// NEW COURSES: AP Environmental Science
// =========================================================
apGuides.apes = {
  title: 'AP Environmental Science',
  exam: 'May 2026 · 3 hrs · MCQ + FRQ (4 types)',
  passRate: '54.1%',
  chapters: [
    makeChapter(1,'Earth Systems & Resources',[
      concepts([
        { term:'Earth\'s Spheres', body:'Lithosphere (rock/soil), hydrosphere (water), atmosphere (gases), biosphere (life). These interact constantly: volcanic eruption (lithosphere) releases CO₂ (atmosphere), which affects ocean chemistry (hydrosphere) and plant growth (biosphere).' },
        { term:'Plate Tectonics', body:'Divergent boundaries: plates move apart (mid-ocean ridges, rift valleys). Convergent: plates collide (subduction, mountain building, trenches). Transform: plates slide past each other (earthquakes, e.g., San Andreas Fault). Drives rock cycle and soil formation.' },
        { term:'Soil Formation & Types', body:'Parent material + time + climate + organisms + topography = soil. Horizons: O (organic), A (topsoil), B (subsoil), C (weathered rock), R (bedrock). Soil degradation: erosion, salinization, desertification. Loam (balanced sand/silt/clay) is ideal for agriculture.' },
        { term:'Atmosphere & Climate', body:'Troposphere (weather), stratosphere (ozone), mesosphere, thermosphere. Solar radiation drives weather. Coriolis effect deflects winds (Northern Hemisphere: clockwise for high pressure, counterclockwise for low). Hadley cells, Ferrel cells, Polar cells drive global wind patterns.' },
      ]),
      vocab([
        { term:'Soil horizon', def:'A distinct layer of soil with characteristic properties — OABCR from surface to bedrock.' },
        { term:'Coriolis effect', def:'Earth\'s rotation deflects moving air and water rightward in the Northern Hemisphere, leftward in the Southern.' },
        { term:'Subduction', def:'When one tectonic plate slides beneath another at a convergent boundary — drives volcanic activity and trench formation.' },
      ]),
      tips(['Know the major biogeochemical cycles: carbon, nitrogen, phosphorus, water. APES FRQs almost always include one.','Soil horizons: O is organic surface litter; A is topsoil where plants live; B accumulates minerals from above.','Coriolis effect appears on nearly every APES exam — apply it to ocean gyres and wind patterns.']),
      quiz([
        { q:"The ozone layer is located in which atmospheric layer?", opts:["Troposphere","Stratosphere","Mesosphere","Thermosphere"], ans:1, exp:"Stratosphere (15–50 km altitude) contains the ozone layer — absorbs UV-B radiation from the sun. CFCs catalytically destroy ozone molecules, creating the 'ozone hole' over Antarctica." },
        { q:"At a subduction zone, what typically occurs?", opts:["Mid-ocean ridges form","One plate slides under another, often creating volcanic arcs and deep trenches","Rift valleys form","The plates slide horizontally past each other"], ans:1, exp:"Convergent boundary (ocean-continent): the denser oceanic plate subducts under the continental plate. Generates volcanoes, earthquakes, and deep sea trenches (e.g., Cascades, Andes, Mariana Trench)." },
        { q:"The most important soil horizon for plant growth is:", opts:["O horizon","A horizon (topsoil — contains organic matter, nutrients, microorganisms)","B horizon","C horizon"], ans:1, exp:"A horizon (topsoil): highest organic matter content, most biological activity, where most plant roots absorb nutrients. Loss of topsoil through erosion is one of the greatest threats to agricultural productivity." },
        { q:"The Coriolis effect in the Northern Hemisphere deflects moving air:", opts:["To the left","To the right","Straight down","Away from the equator"], ans:1, exp:"Coriolis effect: Earth's rotation deflects moving fluids to the RIGHT in the Northern Hemisphere, LEFT in the Southern. Creates clockwise flow in N. hemisphere high-pressure systems and counterclockwise in low-pressure." },
        { q:"Which sphere includes all living organisms and their interactions?", opts:["Lithosphere","Hydrosphere","Atmosphere","Biosphere"], ans:3, exp:"Biosphere: all living organisms on Earth plus their interactions with each other and with the physical environment. It overlaps with all other spheres — life exists in soil (litho), water (hydro), and air (atmo)." },
        { q:"Loam soil is preferred for agriculture because:", opts:["It has the least organic matter","It has a balanced mix of sand (drainage), silt (nutrients), and clay (water retention)","It is the hardest soil type","It contains the most clay"], ans:1, exp:"Loam: roughly 40% sand, 40% silt, 20% clay. The ideal balance provides good drainage (sand), nutrient retention (silt), and some water-holding capacity (clay). Most food crops grow best in loam." },
        { q:"The rock cycle describes how rocks:", opts:["Form only from cooling magma","Can transform between igneous, sedimentary, and metamorphic forms through geological processes over time","Remain permanently in one form","Are created only through tectonic plate collisions"], ans:1, exp:"Rock cycle: igneous (cooling magma) → weathering/erosion → sediments → burial/compression → sedimentary rock → heat/pressure → metamorphic rock → melting → magma again. A continuous cycle driven by plate tectonics and the water cycle." },
        { q:"The San Andreas Fault in California is a:", opts:["Divergent boundary","Convergent boundary","Transform boundary — plates slide past each other horizontally","Hot spot"], ans:2, exp:"Transform boundary: the Pacific Plate and North American Plate slide horizontally past each other — no subduction, no volcanic activity, but frequent severe earthquakes (1906 San Francisco, 1994 Northridge)." },
        { q:"Desertification is best described as:", opts:["The natural formation of deserts","The human-accelerated process of fertile land becoming desert — through overgrazing, deforestation, and poor irrigation practices","A type of soil horizon","Ocean acidification"], ans:1, exp:"Desertification: degradation of dryland ecosystems through human activities. Overgrazing removes vegetation → soil exposure → erosion → loss of nutrients → land can no longer support crops or native vegetation." },
        { q:"The Hadley cell circulation pattern moves air:", opts:["From poles to equator at high altitude","Rising at the equator, moving poleward at high altitude, sinking at ~30° latitude, returning to equator at surface","From 30° to 60° latitude","Horizontally along the equator"], ans:1, exp:"Hadley cells: warm, moist air rises at the equator (creating equatorial rainforests), travels poleward at altitude, cools and descends at about 30° latitude (creating subtropical deserts like the Sahara), returns to equator." }
      ])
    ]),
    makeChapter(2,'Biodiversity & Evolution',[
      concepts([
        { term:'Ecosystem Structure', body:'Producers (autotrophs) → primary consumers → secondary consumers → tertiary consumers → decomposers. Energy transfer: ~10% efficiency per level (10% rule). Biomass pyramids: always narrow at top. Trophic cascade: removing one level affects all others.' },
        { term:'Biomes', body:'Determined by temperature and precipitation: tropical rainforest (high both), desert (high temp, low precip), temperate deciduous forest, grassland/savanna, taiga/boreal forest, tundra (very cold, low precip). Climate change is shifting biome boundaries.' },
        { term:'Biodiversity Threats', body:'HIPPO: Habitat destruction (largest threat), Invasive species, Pollution, Population (human growth), Overexploitation. Mass extinction: we are in the 6th — human-caused at 100–1,000× background rate. Keystone species removal and habitat fragmentation amplify losses.' },
        { term:'Ecosystem Services', body:'Provisioning (food, water, medicine), Regulating (climate regulation, pollination, flood control), Cultural (recreation, spiritual), Supporting (nutrient cycling, soil formation). Loss of services = enormous economic costs.' },
      ]),
      tips(['HIPPO: Habitat loss is the single largest driver of biodiversity loss globally.','Know the biomes by climate: tropical rainforest vs. tropical dry forest vs. savanna — differentiated by precipitation pattern.','Ecosystem services FRQ: list specific services (pollination, carbon sequestration, water purification) with specific examples.']),
      quiz([
        { q:"The HIPPO framework lists the major threats to biodiversity in order. The largest single threat is:", opts:["Invasive species","Overexploitation","Habitat destruction (loss and fragmentation)","Pollution"], ans:2, exp:"Habitat destruction: agricultural expansion, deforestation, urbanization, and wetland drainage are the leading cause of species extinction worldwide. Without habitat, even protected species cannot survive." },
        { q:"The 10% rule in ecology means:", opts:["10% of species are keystone species","Only about 10% of energy from one trophic level is available to the next level","10% of ecosystems are protected globally","10% of biodiversity is found in temperate forests"], ans:1, exp:"10% rule: most energy at each trophic level is lost as heat, in respiration, and in waste. Only ~10% transfers to the next level. This limits food chains to 4–5 levels and explains why smaller populations exist at higher trophic levels." },
        { q:"A tropical rainforest biome is defined by:", opts:["Low temperature and high precipitation","High temperature and high precipitation year-round — the world's most biodiverse terrestrial biome","High temperature and seasonal dry periods","Moderate temperature and precipitation"], ans:1, exp:"Tropical rainforest: near the equator, temperature ~25°C year-round, rainfall >200 cm/year. Contains ~50% of all terrestrial species on only ~6% of land area. Under massive deforestation threat." },
        { q:"Invasive species harm ecosystems by:", opts:["Increasing biodiversity","Competing with native species, often lacking natural predators — driving native species to extinction","Providing food for native predators","Improving soil quality"], ans:1, exp:"Invasive species: out-compete natives because they lack natural predators in the new environment. Examples: kudzu (Southeast US), zebra mussels (Great Lakes), Burmese pythons (Everglades). Often introduced accidentally through trade." },
        { q:"Ecosystem services are valuable because:", opts:["They are only aesthetically important","They provide humanity with trillions of dollars' worth of benefits — food, clean water, air purification, pollination, climate regulation — that markets often fail to price","They are easily replaceable with technology","Only wealthy nations benefit from them"], ans:1, exp:"Ecosystem services: pollinators (bees) support ~$200B in food production annually. Wetlands filter water — cheaper than water treatment plants. Forests sequester carbon and regulate climate. Their loss has enormous economic costs." },
        { q:"The tundra biome is characterized by:", opts:["High biodiversity and warm temperatures","Permafrost, extremely cold temperatures, very short growing seasons, and low precipitation","High precipitation and moderate temperatures","Rich soils and dense forests"], ans:1, exp:"Tundra: located above the Arctic Circle. Permafrost (permanently frozen subsoil) prevents deep root systems. Short summers (plants have weeks to complete life cycle). Rapidly warming due to climate change — permafrost melting releases methane." },
        { q:"Habitat fragmentation harms biodiversity by:", opts:["Increasing genetic diversity","Isolating populations into small patches — reducing genetic diversity, preventing migration/recolonization, and creating 'edge effects'","Making habitats larger","Reducing competition between species"], ans:1, exp:"Fragmentation: breaking continuous habitat into isolated patches (roads, agriculture). Isolates populations (inbreeding, demographic chance → local extinction), prevents recolonization after local extinctions, increases edge habitat where generalist/invasive species thrive." },
        { q:"A keystone species has an effect on its ecosystem:", opts:["Proportional to its population size","Disproportionately large relative to its biomass — removing it causes dramatic ecosystem change","Only at the top trophic level","Limited to its immediate prey species"], ans:1, exp:"Keystone species: sea otters eat sea urchins → without otters, urchins explode → kelp is grazed to extinction → all kelp forest species disappear. The otter's effect is enormous relative to its biomass." },
        { q:"The current biodiversity crisis is often called the 'sixth mass extinction' because:", opts:["Exactly six species are going extinct daily","Species are going extinct at 100–1,000 times the natural background rate, primarily due to human activities","It is the least severe mass extinction in history","It only affects marine species"], ans:1, exp:"Sixth mass extinction: the five previous mass extinctions (including the K-Pg that killed the dinosaurs) had natural causes. The current one is human-driven — the first time one species has caused a mass extinction event." },
        { q:"Which ecosystem provides the greatest carbon sequestration per unit area?", opts:["Temperate grassland","Tropical rainforest","Tundra","Open ocean"], ans:1, exp:"Tropical rainforests have the highest biomass density of any terrestrial ecosystem, storing enormous amounts of carbon in trees and soil. Their destruction releases huge CO₂ quantities — deforestation accounts for ~10% of global emissions." }
      ])
    ]),
    makeChapter(3,'Population Ecology & Agriculture',[
      concepts([
        { term:'Population Dynamics', body:'Exponential growth (unlimited resources: J-curve). Logistic growth (limited: S-curve, with carrying capacity K). Environmental resistance: factors limiting growth (food, space, disease, predation). r-selected: many offspring, low care; K-selected: few offspring, high care.' },
        { term:'Human Population', body:'Demographic transition: high birth/death → high birth/low death (growth) → low birth/death (stability). Total fertility rate (TFR): 2.1 = replacement level. Factors reducing TFR: education (especially of women), urbanization, access to family planning.' },
        { term:'Agriculture', body:'The Green Revolution increased yields but: required chemical inputs, favored large farms, reduced crop diversity, and caused soil/water problems. Monocultures increase efficiency but increase vulnerability to pests and disease. Sustainable alternatives: organic, permaculture, IPM, polycultures.' },
      ]),
      tips(['Demographic transition model: know all 4 stages and what country types are in each.','Green Revolution pros AND cons are both tested heavily on APES.','TFR of 2.1 = replacement level — the average needed to keep population stable. Countries below this have aging/shrinking populations.']),
      quiz([
        { q:"Carrying capacity (K) in logistic population growth is defined as:", opts:["The maximum rate of population growth","The population size at which growth rate is maximum","The maximum population a habitat can sustainably support given its available resources","The population size at birth"], ans:2, exp:"Carrying capacity: the maximum population size that an ecosystem can sustain indefinitely given available resources (food, water, space, etc.). At K, birth rate = death rate, and population growth = 0." },
        { q:"The demographic transition model predicts that as countries industrialize:", opts:["Birth and death rates both remain high","Birth rates stay high while death rates fall first (rapid growth), then birth rates eventually fall too (slow growth → stability)","Death rates increase with industrialization","Population always reaches zero growth immediately"], ans:1, exp:"Demographic transition: Stage 1 (pre-industrial): high birth, high death. Stage 2: death rates fall (medicine, food security) → rapid growth. Stage 3: birth rates fall (education, urbanization). Stage 4: low birth, low death → slow/no growth." },
        { q:"Total Fertility Rate (TFR) of 2.1 represents:", opts:["The maximum possible birth rate","Replacement level fertility — the average children per woman needed to maintain stable population (accounting for child mortality)","The ideal family size","The fertility rate of industrialized nations"], ans:1, exp:"TFR = 2.1 is replacement level: one child replaces each parent, with 0.1 accounting for child mortality. Above 2.1 = population growth. Below 2.1 = eventual population decline (many European countries and Japan are below)." },
        { q:"The Green Revolution's most significant NEGATIVE consequences include:", opts:["Decreased food production","Increased chemical fertilizer and pesticide use, reduced crop genetic diversity, groundwater depletion, and increased inequality favoring large farms","Reduced crop yields","Elimination of traditional farming entirely"], ans:1, exp:"Green Revolution trade-offs: fed billions BUT required expensive inputs (fertilizers, pesticides, irrigation), favored wealthy large-scale farmers, dramatically reduced crop genetic diversity (vulnerability to disease), and depleted groundwater." },
        { q:"An r-selected species strategy produces:", opts:["Few offspring with heavy parental investment","Many offspring, early reproductive maturity, little parental care, adapted to unstable environments","Population growth limited by K","Large body size and long lifespan"], ans:1, exp:"r-selected: maximize reproduction rate. Examples: insects, annual weeds, most fish. Many small offspring, most die young, but the strategy works in unpredictable environments where rapid colonization matters more than individual survival." },
        { q:"Integrated Pest Management (IPM) differs from conventional pesticide use by:", opts:["Using no pesticides whatsoever","Using a combination of biological controls, resistant crop varieties, habitat manipulation, and pesticides as a LAST resort to minimize environmental impact","Applying the maximum legal amount of pesticide","Focusing only on indoor pest control"], ans:1, exp:"IPM: multi-strategy approach that minimizes pesticide use. Biological controls (natural predators), crop rotation, resistant varieties, trapping, and monitoring — pesticides only when threshold is exceeded. Reduces resistance, environmental impact, and cost." },
        { q:"Soil erosion is most severe when:", opts:["Soil is covered with vegetation","Agricultural fields are left bare (no cover crops) and steep slopes lack vegetative cover — rain and wind remove topsoil","Rainfall is very light","Crop rotation is practiced"], ans:1, exp:"Erosion: the two main agents are water (sheet and rill erosion on slopes) and wind. Both are dramatically worse without vegetative cover. Contour plowing, terracing, cover crops, and windbreaks all reduce erosion." },
        { q:"Food security is most threatened by which current trend?", opts:["Increasing crop diversity worldwide","Loss of pollinators, soil degradation, water scarcity, and climate change — simultaneously affecting agricultural productivity","Decrease in food production efficiency","Reduced human population growth"], ans:1, exp:"Food security threats: pollinator decline (30% of food crops depend on bees), topsoil loss (takes 500+ years to form an inch), aquifer depletion (Ogallala Aquifer), climate shifts affecting growing seasons. All occurring simultaneously." },
        { q:"The demographic transition model's Stage 2 is characterized by:", opts:["Low birth rate and low death rate","High birth rate and rapidly falling death rate — the stage of maximum population growth","Low birth rate and high death rate","Stable population with low birth and death rates"], ans:1, exp:"Stage 2: Death rate drops first (improvements in medicine, sanitation, food security) while birth rate remains high (social norms don't change immediately). Maximum rate of population increase. Most of sub-Saharan Africa is currently in Stage 2." },
        { q:"Which practice MOST directly addresses soil salinization caused by irrigation?", opts:["Adding more chemical fertilizer","Improving drainage systems and switching to drip irrigation to reduce salt accumulation","Increasing irrigation frequency","Planting monocultures"], ans:1, exp:"Salinization: irrigation water evaporates, leaving salt behind. Over time, soil becomes toxic to crops. Prevention: better drainage (flush salts down), drip irrigation (water delivered to roots, less evaporation), salt-tolerant crops." }
      ])
    ]),
    makeChapter(4,'Energy Resources & Pollution',[
      concepts([
        { term:'Fossil Fuels & Climate', body:'Coal, oil, natural gas: formed from ancient organic matter. Burning releases stored carbon as CO₂. Greenhouse effect: CO₂, CH₄, N₂O, water vapor trap heat. Positive feedbacks amplify warming: Arctic melting → less reflectivity (albedo) → more warming → more melting. IPCC consensus: ~1.1°C warming since pre-industrial.' },
        { term:'Renewable Energy', body:'Solar PV (photovoltaic), concentrating solar, wind, hydroelectric, geothermal, biomass. Each has environmental trade-offs. Solar/wind: intermittent (need storage). Hydro: disrupts rivers. Biofuels: land use competition. No energy source is without impact.' },
        { term:'Air Pollution', body:'Primary pollutants: emitted directly (CO, PM, SO₂, NOₓ, VOCs). Secondary: form in atmosphere (ozone, particulate matter from NOₓ+VOCs, acid rain from SO₂+NOₓ+water). CAA (Clean Air Act 1970) and its amendments: regulated 6 criteria pollutants. Thermal inversion traps pollutants.' },
        { term:'Water Pollution', body:'Point source: identifiable discharge location (pipe, outfall). Nonpoint source: diffuse (agricultural runoff, urban stormwater). CWA (Clean Water Act 1972). Eutrophication from N and P. Dead zones (Gulf of Mexico). Bioaccumulation/biomagnification of persistent toxins.' },
      ]),
      tips(['Know primary vs. secondary pollutants: smog is a secondary pollutant.','Biomagnification: persistent lipophilic toxins (DDT, mercury, PCBs) increase in concentration up the food chain.','APES FRQs almost always ask about at least ONE environmental law — CAA, CWA, CERCLA (Superfund), ESA.']),
      quiz([
        { q:"The primary greenhouse gas responsible for most human-caused climate change is:", opts:["Methane (CH₄)","Carbon dioxide (CO₂) from fossil fuel combustion and deforestation","Nitrous oxide (N₂O)","Water vapor"], ans:1, exp:"CO₂: primary driver of anthropogenic climate change. Although methane is more potent per molecule, CO₂ is far more abundant and has longer atmospheric residence time. Its concentration has risen from ~280 ppm (pre-industrial) to ~420 ppm." },
        { q:"Photovoltaic (PV) solar panels convert:", opts:["Sunlight to heat to electricity","Sunlight directly to electricity via the photovoltaic effect","Wind energy to electricity","Chemical energy to electricity"], ans:1, exp:"PV panels: semiconductors (typically silicon) absorb photons and release electrons directly as electricity. No combustion, no water use, no emissions during operation. Trade-offs: manufacturing impact, land use, intermittency." },
        { q:"Acid rain primarily forms from:", opts:["CO₂ dissolving in rainwater","SO₂ and NOₓ emissions reacting with water vapor in the atmosphere to form sulfuric and nitric acids","Ozone depletion","Industrial dust particles"], ans:1, exp:"Acid rain: SO₂ (coal power plants, smelters) + NOₓ (vehicles, power plants) + H₂O → H₂SO₄ + HNO₃. Falls hundreds of miles from sources. Damages forests, acidifies lakes, corrodes stone buildings and infrastructure." },
        { q:"Biomagnification explains why:", opts:["Plants absorb more toxins than animals","Top predators have the highest concentrations of persistent toxins — toxins accumulate in fat and don't break down, concentrating at each trophic level","Toxins evaporate from the ocean","Herbivores are more toxic than carnivores"], ans:1, exp:"Biomagnification: fat-soluble, persistent compounds (DDT, mercury, PCBs) aren't excreted — they accumulate in fat tissue. Each predator consumes many prey → concentrates their toxins. Top predators (tuna, eagles, humans) have the highest concentrations." },
        { q:"A thermal inversion worsens air pollution because:", opts:["It creates wind that disperses pollutants","A layer of warm air traps cool, polluted air near the surface — preventing normal vertical mixing and dispersal","It increases rainfall that washes out pollutants","It raises temperatures enough to destroy pollutants"], ans:1, exp:"Thermal inversion: normally warm air is at surface and cold at altitude (allows mixing). During inversion, a warm air layer sits above cold surface air — a lid that traps pollutants. Los Angeles's geography makes it especially vulnerable." },
        { q:"The Clean Water Act (1972) primarily regulates:", opts:["Drinking water quality in homes","Point source discharge into US waters — requiring permits (NPDES) and setting water quality standards","Groundwater quality","Ocean pollution only"], ans:1, exp:"Clean Water Act: landmark legislation requiring permits for any point-source discharge to navigable waters. Set 'fishable and swimmable' as the goal. Dramatically reduced industrial pollution of rivers." },
        { q:"Eutrophication in aquatic ecosystems results from:", opts:["Acid rain lowering pH","Excess nutrient (nitrogen and phosphorus) runoff causing algal blooms that deplete oxygen when the algae die and decompose","Oil spills blocking sunlight","Thermal pollution from power plants"], ans:1, exp:"Eutrophication: nutrient pollution (agricultural fertilizers, sewage) → algal bloom → algae shade out underwater plants → algae die → decomposers consume O₂ → hypoxic zone → fish kills. The Gulf of Mexico dead zone is caused by Mississippi River nutrient runoff." },
        { q:"Compared to coal, natural gas combustion produces:", opts:["More CO₂ per energy unit","Less CO₂ per energy unit but methane leakage during extraction partially offsets this benefit","The same CO₂","No greenhouse gases at all"], ans:1, exp:"Natural gas: burns cleaner than coal (about half the CO₂ per kWh). BUT: methane is 80× more potent than CO₂ as a greenhouse gas over 20 years. Leakage during fracking and pipeline transport can significantly reduce the climate advantage." },
        { q:"The Endangered Species Act (ESA, 1973) protects species by:", opts:["Requiring all species to be listed","Prohibiting the 'taking' of listed species and requiring federal agencies to consult on actions that might jeopardize listed species or their critical habitat","Requiring payment to property owners who have listed species on their land","Protecting only vertebrate species"], ans:1, exp:"ESA: species are listed as threatened or endangered. 'Taking' (harming, harassing, pursuing, wounding, or killing) listed species is prohibited. Critical habitat must be designated. Recovery plans must be developed. The most powerful US wildlife law." },
        { q:"Nuclear power's main environmental advantage over fossil fuels is:", opts:["It produces no radioactive waste","It generates electricity with very low greenhouse gas emissions during operation","It is cheaper than solar and wind","It requires no water for cooling"], ans:1, exp:"Nuclear advantages: very low CO2 emissions during operation (lifecycle emissions comparable to wind). Very high energy density. Disadvantages: radioactive waste (long-lived storage problem), accident risk (Chernobyl, Fukushima), high capital cost, uranium mining impacts." }
      ])
    ]),
    makeChapter(5,'Global Change & Sustainability',[
      concepts([
        { term:'Climate Change Impacts', body:'Sea level rise (thermal expansion + ice melt). More frequent/intense extreme weather events. Ocean acidification (CO₂ + H₂O → carbonic acid → coral bleaching, shellfish dissolution). Shifting species ranges, earlier seasons. Arctic warming 3–4× faster than global average.' },
        { term:'Ozone Depletion', body:'CFCs (refrigerants, aerosols) are the primary cause. Cl radicals catalytically destroy O₃ (one Cl atom destroys ~100,000 ozone molecules). Montreal Protocol (1987): phased out CFCs — the most successful international environmental agreement. Ozone hole slowly healing.' },
        { term:'Sustainability & Policy', body:'Tragedy of the Commons: shared resources are overexploited when individuals benefit from overuse but costs are spread to all. Solutions: privatization, government regulation, community management (Ostrom). Sustainability: meeting present needs without compromising future generations\' ability to meet theirs (Brundtland definition).' },
      ]),
      tips(['Montreal Protocol = the APES FRQ answer for ozone recovery. It is the most successful international environmental treaty.','Ocean acidification is separate from temperature change — it is a chemical effect of CO₂ dissolving in seawater.','Tragedy of the Commons: know specific examples (fishing, groundwater, atmosphere) and specific solutions for each.']),
      quiz([
        { q:"Ocean acidification occurs because:", opts:["Ocean water heats up and releases acid","CO₂ dissolves in seawater, forming carbonic acid, which lowers ocean pH","Acid rain falls directly into the ocean","Nutrient runoff causes chemical reactions"], ans:1, exp:"Ocean acidification: CO₂(g) + H₂O → H₂CO₃ (carbonic acid) → H⁺ + HCO₃⁻. The increased H⁺ concentration lowers pH. Already dropped from 8.2 to 8.1 — that's a 26% increase in acidity. Threatens shellfish, coral reefs, and marine food webs." },
        { q:"The Montreal Protocol (1987) successfully addressed ozone depletion by:", opts:["Reducing all greenhouse gas emissions","Phasing out the production and use of CFCs and other ozone-depleting substances — the most successful international environmental treaty","Planting forests to absorb chemicals","Requiring all nations to reduce CO₂ emissions"], ans:1, exp:"Montreal Protocol: nations agreed to phase out CFCs by a specific schedule. CFCs replaced with HFCs (less ozone-depleting but potent greenhouse gases — later addressed by the Kigali Amendment). The ozone hole is slowly healing." },
        { q:"The Tragedy of the Commons occurs when:", opts:["A commons are privately owned and overprotected","Individuals overexploit shared resources because each benefits from maximum use while the costs are distributed to all users — leading to collective ruin","Governments regulate shared resources too strictly","Only wealthy nations exploit shared resources"], ans:1, exp:"Tragedy of the Commons (Hardin, 1968): each fisherman maximizes their catch (individual benefit) while the shared fishery is depleted (shared cost). No individual has incentive to restrain — the rational choice for each leads to collective ruin." },
        { q:"Sea level rise from climate change is caused by:", opts:["Changes in ocean salinity only","Both thermal expansion of warming water AND melting of land-based ice (glaciers and ice sheets — NOT sea ice)","Increased river discharge only","Tectonic plate movement"], ans:1, exp:"Sea level rise: ~50% from thermal expansion (warmer water takes more volume), ~50% from melting land ice (glaciers, Greenland, West Antarctica). Melting sea ice doesn't raise sea level (already displaces water). Risk to coastal cities worldwide." },
        { q:"The Kyoto Protocol (1997) and Paris Agreement (2015) both attempt to address climate change by:", opts:["Banning all fossil fuel use immediately","Setting international targets for reducing greenhouse gas emissions","Regulating ozone-depleting substances","Creating a global carbon market only"], ans:1, exp:"Paris Agreement: 196 nations set nationally determined contributions (NDCs) to limit warming to 'well below 2°C above pre-industrial levels, pursuing efforts to limit to 1.5°C.' Unlike Kyoto, it includes developing nations but relies on voluntary pledges." },
        { q:"Sustainable development is defined as:", opts:["Economic growth at any environmental cost","Development that meets present needs without compromising future generations' ability to meet their needs","Returning all land to pre-industrial conditions","Eliminating industrial production"], ans:1, exp:"Brundtland Commission definition (1987): 'Development that meets the needs of the present without compromising the ability of future generations to meet their own needs.' Balances economic growth, social equity, and environmental protection." },
        { q:"The most direct ecological impact of ozone depletion is:", opts:["Increased temperatures globally","Increased UV-B radiation reaching Earth's surface — causing increased skin cancer, cataracts, immune suppression, and damage to marine phytoplankton","Acid rain formation","Sea level rise"], ans:1, exp:"Ozone depletion: UV-B normally absorbed by stratospheric ozone. Without ozone protection: skin cancer (UV damages DNA), eye cataracts, immune suppression, damage to phytoplankton (base of marine food web). Worst over Antarctica ('ozone hole')." },
        { q:"A carbon tax is a policy tool that addresses climate change by:", opts:["Directly removing CO₂ from the atmosphere","Making fossil fuels more expensive to reflect their true social cost — incentivizing a shift to cleaner energy through market forces","Banning carbon directly","Requiring all companies to plant trees"], ans:1, exp:"Carbon tax: price on carbon emissions. Makes fossil fuels reflect their climate cost → incentivizes businesses and consumers to use less carbon-intensive options. Revenue can be used for clean energy investment or returned to citizens as dividends." },
        { q:"Which of the following BEST describes a 'cap and trade' system?", opts:["A government sets a maximum level of emissions (cap), then allows businesses to buy and sell permits to emit up to that total","A tax on all carbon-intensive industries","A ban on specific pollutants","A voluntary agreement for businesses to reduce emissions"], ans:0, exp:"Cap and trade: the total emissions allowed are capped. Companies receive permits. Those who reduce emissions cheaply can sell excess permits to those for whom reduction is costly. Economic efficiency in achieving the environmental target. EU ETS is the largest example." },
        { q:"Elinor Ostrom's research on the Tragedy of the Commons showed that:", opts:["Common resources always collapse without privatization or government control","Many communities have successfully developed their own rules and institutions to sustainably manage common resources — community management is a viable third path","Government regulation is always the best solution","Private property rights are the only solution"], ans:1, exp:"Ostrom (2009 Nobel Prize): studied fisheries, forests, and irrigation systems where communities successfully avoided overexploitation without privatization or government control. Communities with long tenure, clear rules, and participation can manage commons sustainably." }
      ])
    ]),
  ]
};

