apGuides.apcsa = {
  title: 'AP Computer Science A',
  exam: 'May 2026 · 3 hrs · MCQ + FRQ (4 types)',
  passRate: '67.2%',
  chapters: [
    makeChapter(1,'Primitive Types & Variables',[
      concepts([
        { term:'Primitive Data Types', body:'int: whole numbers (-2³¹ to 2³¹-1). double: decimal numbers (floating point). boolean: true/false. char: single character (not commonly tested). AP CS A does NOT test byte, short, long, float directly.' },
        { term:'Type Casting', body:'int to double: automatic widening. double to int: requires explicit cast (int)(3.7) = 3 (truncates, doesn\'t round). Integer division: 7/2 = 3 (not 3.5). 7.0/2 = 3.5. 7/2.0 = 3.5. Know which operations produce int vs double.' },
        { term:'String Basics', body:'String is a class (not a primitive). Concatenation: "Hello" + " " + "World". Concatenating int with String converts int to String: "x = " + 5 = "x = 5". String methods: length(), substring(a,b), indexOf(str), equals(), compareTo().' },
        { term:'Operators', body:'Arithmetic: +, -, *, /, % (modulo). Comparison: ==, !=, <, >, <=, >=. Logical: && (AND), || (OR), ! (NOT). Assignment: =, +=, -=, *=, /=, %=. Increment: ++ (post/pre), -- (post/pre). Short-circuit evaluation: && stops at first false; || stops at first true.' },
      ]),
      vocab([
        { term:'Integer division', def:'Dividing two ints always produces an int — the decimal is truncated (not rounded). 7/2 = 3, not 3.5.' },
        { term:'Modulo (%)', def:'Returns the remainder of division. 7 % 3 = 1. Used to check even/odd (n%2==0), cycles, limiting ranges.' },
        { term:'Type casting', def:'Converting between data types: (int) 3.9 → 3. Explicit cast required for narrowing (double→int); widening (int→double) is automatic.' },
      ]),
      tips(['Integer division truncates (floor for positives): 7/2 = 3. Always check if an int operation needs a double result.','Modulo (%) is on every AP CS A exam — use it to check evenness, extract digits, and create cyclic behavior.','Comparing Strings: use .equals() not == (== checks reference, not content).']),
      quiz([
        { q:"What is the value of 17 % 5?", opts:["3","2","1","0"], ans:1, exp:"17 % 5: 17 = 3×5 + 2. The remainder is 2. Modulo returns the remainder of integer division." },
        { q:"What is the result of (int)(7.9) in Java?", opts:["8","7","7.9","0"], ans:1, exp:"Explicit cast (int) truncates (not rounds) toward zero. (int)(7.9) = 7. (int)(-7.9) = -7. This is an extremely common AP CS A question." },
        { q:"What does 5/2 evaluate to in Java?", opts:["2.5","3","2","2.0"], ans:2, exp:"Integer division: 5 and 2 are both ints. 5/2 = 2 (the .5 is discarded). To get 2.5, you need 5.0/2 or (double)5/2 or 5/2.0." },
        { q:"Which operator checks if two int values are equal in Java?", opts:["=","equals()","==","is"], ans:2, exp:"== compares primitive values for equality. For objects (including Strings), == checks if they reference the same object — not the same content. Use .equals() for String content comparison." },
        { q:"What is the value of 'Hello' + 3 + 4 in Java?", opts:["Hello7","Hello34","Error","7Hello"], ans:1, exp:"String concatenation evaluates left to right: 'Hello' + 3 = 'Hello3' (String). 'Hello3' + 4 = 'Hello34' (String). If it were 3 + 4 + 'Hello': 7 + 'Hello' = '7Hello'." },
        { q:"The logical operator && (AND) returns true only when:", opts:["Either condition is true","Both conditions are true","The first condition is true","The second condition is true"], ans:1, exp:"&&: both must be true. Short-circuit: if the first operand is false, Java doesn't evaluate the second (result is definitely false). Compare with || (OR): true if AT LEAST one is true." },
        { q:"What is the value of x after: int x = 5; x += 3;", opts:["5","3","8","15"], ans:2, exp:"x += 3 is equivalent to x = x + 3 = 5 + 3 = 8. Compound assignment operators +=, -=, *=, /=, %= are shorthand." },
        { q:"Which of the following correctly declares a double variable named price with value 9.99?", opts:["int price = 9.99;","double price = 9.99;","double price = 9;","price = 9.99;"], ans:1, exp:"double price = 9.99; declares a variable of type double named price and initializes it to 9.99. 'int price = 9.99' would cause a compilation error (can't store a double in an int without casting)." },
        { q:"The expression !true evaluates to:", opts:["true","false","1","null"], ans:1, exp:"! is the logical NOT operator. !true = false. !false = true. Used for toggling boolean values and reversing conditions." },
        { q:"What does the String method .length() return?", opts:["The last character","The number of characters in the String","The position of a substring","Whether two Strings are equal"], ans:1, exp:"str.length() returns the number of characters (an int). 'Hello'.length() = 5. Note: for arrays, you use array.length (no parentheses). For ArrayList, use .size()." }
      ])
    ]),
    makeChapter(2,'Control Flow',[
      concepts([
        { term:'Conditionals', body:'if/else if/else: evaluates conditions in order, executes first true branch. Switch: matches exact values. Nested if: an if inside another if. Short-circuit: in && and ||, Java stops evaluating as soon as the result is determined.' },
        { term:'Loops', body:'for loop: for(init; condition; update). while loop: check condition before each iteration. do-while: check condition after first iteration. Enhanced for loop (for-each): for(Type var : collection) — iterates through all elements. break: exits loop. continue: skips to next iteration.' },
        { term:'Loop Patterns', body:'Accumulator: sum += current. Counter: count++. Max/min tracking. Linear search: check each element until found. Traversal: visit every element. Off-by-one errors: check if loop should be < or <=, and whether indexing starts at 0.' },
      ]),
      tips(['Off-by-one errors: remember arrays/Strings are 0-indexed. for(int i=0; i<arr.length; i++) accesses arr[0] through arr[arr.length-1].','for-each loops cannot be used to modify array elements (they use a copy).','String substring(a,b) includes index a but EXCLUDES index b. "Hello".substring(1,4) = "ell".']),
      quiz([
        { q:"How many times does this loop execute: for(int i=0; i<5; i++)?", opts:["4","5","6","0"], ans:1, exp:"Loop: i starts at 0, runs while i < 5. Values of i: 0, 1, 2, 3, 4. That's 5 iterations. The condition i<5 means it stops BEFORE reaching 5." },
        { q:"What does 'Hello'.substring(1, 4) return?", opts:["Hell","ello","ell","Helo"], ans:2, exp:"substring(startIndex, endIndex): includes startIndex, EXCLUDES endIndex. Indices: H(0), e(1), l(2), l(3), o(4). substring(1,4) → e(1), l(2), l(3) = 'ell'." },
        { q:"A while loop vs a for loop: you should use a while loop when:", opts:["You always know exactly how many iterations are needed","You don't know in advance how many iterations are needed — the loop continues while a condition holds","You need to iterate through an array","The loop body executes exactly once"], ans:1, exp:"While loops: use when iteration count is unknown in advance (reading until end of file, waiting for user input, searching until found). For loops: use when iteration count is known (loop n times, traverse array)." },
        { q:"What is the value of sum after: int sum = 0; for(int i=1; i<=4; i++) { sum += i; }?", opts:["4","10","6","15"], ans:1, exp:"Accumulator pattern: sum starts at 0. Add i each iteration: sum = 0+1+2+3+4 = 10. The loop runs for i = 1, 2, 3, 4." },
        { q:"The enhanced for-each loop: for(int x : nums) can be used to:", opts:["Modify each element of nums","Only read elements — x is a copy, changes to x don't change nums","Track the index of each element","Replace elements at even indices only"], ans:1, exp:"For-each: creates a copy of each element. Changing x does NOT change the array. Use a regular for loop with index if you need to modify elements: nums[i] = newValue." },
        { q:"What does 'break' do inside a loop?", opts:["Skips the current iteration and continues with the next","Immediately exits the entire loop","Exits the program","Goes back to the beginning of the loop"], ans:1, exp:"break: immediately exits the innermost loop (or switch statement). Useful for early termination when a condition is met (e.g., found the target in a linear search). 'continue' skips the current iteration but stays in the loop." },
        { q:"An off-by-one error in array access typically causes:", opts:["A compilation error","An ArrayIndexOutOfBoundsException at runtime","Incorrect output only","A logic error with no exception"], ans:1, exp:"ArrayIndexOutOfBoundsException: accessing array index that doesn't exist (negative or ≥ length). Most common cause: loop using i<=arr.length instead of i<arr.length. The last valid index is always arr.length - 1." },
        { q:"What does this return: String s = 'computer'; s.indexOf('p')?", opts:["2","3","c","false"], ans:1, exp:"indexOf(str): returns the index (position) of the FIRST occurrence of the argument. 'computer': c(0), o(1), m(2), p(3). indexOf('p') = 3. Returns -1 if not found." },
        { q:"Which loop always executes its body at least once?", opts:["for loop","while loop","do-while loop","for-each loop"], ans:2, exp:"do-while: the body executes FIRST, then the condition is checked. This guarantees at least one execution. Used when you need the body to run once regardless (e.g., display a menu, then loop while user doesn't choose 'quit')." },
        { q:"In Java, boolean conditions in if statements must be:", opts:["Integers (0 or 1)","Actual boolean expressions (true/false) — unlike C, you cannot use integers as conditions","Strings","Always comparisons with =="], ans:1, exp:"Java: you MUST use actual boolean expressions in if conditions. if(x) where x is an int is a compilation error in Java (unlike C/C++). Use if(x != 0) or if(x > 0) explicitly." }
      ])
    ]),
    makeChapter(3,'Object-Oriented Programming',[
      concepts([
        { term:'Classes & Objects', body:'Class: blueprint/template defining state (instance variables) and behavior (methods). Object: an instance of a class. new keyword: creates an object in memory. Constructor: special method with same name as class, no return type, called at object creation.' },
        { term:'Encapsulation', body:'Private instance variables: data hiding. Public methods: controlled access. Getter (accessor): returns the value of a private variable. Setter (mutator): changes the value of a private variable, often with validation. this keyword: refers to the current object.' },
        { term:'Inheritance', body:'extends keyword: subclass inherits all public/protected members from superclass. super(): calls parent constructor. super.method(): calls parent method. IS-A relationship: a Dog IS-A Animal. Override: redefine a method in the subclass. instanceof: tests object type.' },
        { term:'Polymorphism & Interfaces', body:'Polymorphism: a reference variable of type Superclass can hold a Subclass object. The actual method called is determined at runtime (dynamic dispatch). Overloading: same method name, different parameter list (resolved at compile time). Abstract class: cannot be instantiated. Interface: contract of methods (implements).' },
      ]),
      tips(['AP CS A FRQ Part A: almost always writing a method inside a class. Study the class header and instance variables carefully before writing code.','Override vs. overload: override = same signature in subclass; overload = same name, different parameters in same class.','null object reference: calling a method on null → NullPointerException. Always check if a reference could be null before calling methods on it.']),
      quiz([
        { q:"In Java, 'private' instance variables can be accessed from:", opts:["Any class in the program","Only within the class where they are declared","Any class in the same package","The class and all subclasses"], ans:1, exp:"private: most restrictive access modifier. Only the class ITSELF can access private members. Subclasses cannot access private members of the parent (they use public/protected getters). This is encapsulation." },
        { q:"A constructor differs from a regular method because:", opts:["It can return any value","It has no return type (not even void) and has the same name as the class","It uses a different access modifier","It runs automatically every hour"], ans:1, exp:"Constructor: same name as class, NO return type (not even void). Called automatically when 'new ClassName()' is executed. Creates and initializes the object. If you define no constructor, Java provides a default no-arg constructor." },
        { q:"Inheritance using 'extends' creates an IS-A relationship. Which correctly describes IS-A?", opts:["Any class can extend any other class","The subclass IS a more specific version of the superclass — a Dog IS-A Animal, so Dog extends Animal","The superclass extends the subclass","The two classes have the same methods"], ans:1, exp:"IS-A: if class B extends class A, every B object IS an A object. A Dog IS an Animal. A SavingsAccount IS a BankAccount. This is the basis for polymorphism — you can use a Dog anywhere an Animal is expected." },
        { q:"super() in a subclass constructor:", opts:["Creates a new superclass object","Calls the parent class constructor — must be the first statement in the subclass constructor","Returns the parent class","Is optional in all subclass constructors"], ans:1, exp:"super(): calls the parent's constructor. If not written explicitly, Java automatically inserts super() (no-arg parent constructor). If the parent has no no-arg constructor, you must explicitly call super(args)." },
        { q:"Dynamic dispatch (polymorphism) in Java means:", opts:["The compiler determines which method version to call at compile time","The JVM determines which version of an overridden method to call at runtime based on the actual object type — not the reference type","Methods can be called dynamically from other classes","Method names can change at runtime"], ans:1, exp:"Dynamic dispatch: if you have Animal a = new Dog(), and Dog overrides Animal.speak(), then a.speak() calls DOG's version at runtime — even though the reference type is Animal. The actual object type determines which override runs." },
        { q:"Method overloading (NOT overriding) occurs when:", opts:["A subclass redefines a parent method with the same signature","The same class has multiple methods with the same name but different parameter lists","A method calls itself","Two classes have methods with the same name"], ans:1, exp:"Overloading: same class, same method name, different parameters (type, number, or order). println(int), println(double), println(String) are all overloads of the same method name. Resolved at compile time based on argument types." },
        { q:"The 'this' keyword refers to:", opts:["The parent class object","The current object — the instance that the method is being called on","A static variable","The next object to be created"], ans:1, exp:"this: refers to the current instance. Used to distinguish instance variables from parameters with the same name: this.name = name (left is instance variable, right is parameter). Also used to call another constructor in the same class: this(args)." },
        { q:"An abstract class in Java:", opts:["Can be instantiated with new","Cannot be instantiated — it serves as a blueprint for subclasses; it may have abstract methods (no body) that subclasses must implement","Has only static methods","Has no instance variables"], ans:1, exp:"Abstract class: marked with 'abstract' keyword. Cannot create objects directly with new AbstractClass(). Subclasses must implement all abstract methods. Used when you want to share code but the base class concept is too general to be concrete." },
        { q:"What exception occurs when you call a method on a null reference?", opts:["ArrayIndexOutOfBoundsException","ClassCastException","NullPointerException","IllegalArgumentException"], ans:2, exp:"NullPointerException: the most common Java runtime error. Calling any method or accessing any field on a null reference causes this. String s = null; s.length() → NullPointerException." },
        { q:"When a subclass overrides a method from its parent, it should use the same:", opts:["Object type but different method name","Method name, parameter list, and return type (same signature)","Access modifier only","Variable names inside the method"], ans:1, exp:"Override: exact same signature (name + parameters + return type) in the subclass. The @Override annotation (optional but good practice) makes Java verify you're actually overriding, not accidentally overloading." }
      ])
    ]),
    makeChapter(4,'Arrays & ArrayLists',[
      concepts([
        { term:'Arrays', body:'Fixed size (set at creation). Declaration: int[] nums = new int[5]; (5 zeros). Access: nums[0] through nums[4]. Length: nums.length (no parentheses). 2D arrays: int[][] grid = new int[3][4]; Access: grid[row][col]. Default values: 0 for int, null for objects, false for boolean.' },
        { term:'ArrayLists', body:'Dynamic size — grows/shrinks. Must import java.util.ArrayList. Syntax: ArrayList<String> list = new ArrayList<String>(); Methods: add(obj), add(index,obj), get(index), set(index,obj), remove(index), size(), contains(obj). Only stores objects (not primitives — use Integer, Double, Boolean wrappers).' },
        { term:'Common Algorithms', body:'Traversal: iterate through all elements. Search: linear search (check each). Sort: selection sort (find min, swap to front) and insertion sort (insert each element in correct position). String/array manipulation. The AP CS A Labs include these patterns.' },
      ]),
      tips(['Arrays vs ArrayList: arrays have fixed size and can store primitives; ArrayLists are dynamic and can store only objects (use wrapper types).','When removing elements from an ArrayList in a loop, iterate BACKWARDS to avoid skipping elements.','2D array traversal: two nested loops — outer for rows, inner for columns.']),
      quiz([
        { q:"For an array int[] arr = new int[5], valid indices are:", opts:["1 through 5","0 through 5","0 through 4","1 through 4"], ans:2, exp:"Arrays are 0-indexed. An array of size 5 has indices 0, 1, 2, 3, 4. The last valid index is always arr.length - 1 = 4. Accessing arr[5] → ArrayIndexOutOfBoundsException." },
        { q:"ArrayList<Integer> is used instead of ArrayList<int> because:", opts:["int is too large","ArrayLists can only hold objects — int is a primitive, Integer is its wrapper class","Integer is faster than int","ArrayLists don't support numbers"], ans:1, exp:"Generics require object types. Java automatically autoboxes int to Integer and unboxes Integer to int when needed. ArrayList<Integer> stores Integer objects, not primitive ints." },
        { q:"list.remove(2) on an ArrayList:", opts:["Removes the element with VALUE 2","Removes the element at INDEX 2 (the third element)","Removes the last two elements","Removes elements greater than 2"], ans:1, exp:"remove(int index) removes the element at that position. To remove by VALUE, you'd need to pass the value wrapped as an Integer: list.remove(Integer.valueOf(2)). This distinction appears on AP CS A exams." },
        { q:"What is the default value of elements in int[] arr = new int[3]?", opts:["null","1","0","undefined"], ans:2, exp:"Java initializes array elements to default values: 0 for int/double/long, false for boolean, null for objects (String, etc.). int[] arr = new int[3] creates {0, 0, 0}." },
        { q:"To access the element in row 2, column 3 of a 2D array called grid:", opts:["grid[3][2]","grid[2][3]","grid[2,3]","grid.get(2,3)"], ans:1, exp:"2D array access: grid[row][column]. Row 2, column 3 = grid[2][3]. Note: grid[3][2] would access row 3, column 2 — a different element (and a common error)." },
        { q:"When iterating through an ArrayList and removing elements, why should you iterate backwards?", opts:["Forward iteration is faster","Backwards iteration prevents index shifting errors — removing element at index i shifts all subsequent elements left, causing you to skip elements if going forward","ArrayLists can't be iterated forward","The last elements should be removed first"], ans:1, exp:"Forward removal problem: remove index 2 → element at index 3 shifts to index 2. Next iteration checks index 3 — but the old index-3 element is now at index 2 and gets skipped. Backwards iteration avoids this." },
        { q:"The ArrayList method .size() returns:", opts:["The maximum capacity","The number of elements currently stored in the ArrayList","The memory allocated to the list","The index of the last element"], ans:1, exp:".size() returns the CURRENT number of elements stored. Unlike arrays where .length is the allocated size (which may have empty spots), .size() is always the actual count of objects in the ArrayList." },
        { q:"In selection sort, each pass through the array:", opts:["Inserts one element in the correct position","Finds the minimum element in the unsorted portion and swaps it to the front of that portion","Compares adjacent elements and swaps if out of order","Splits the array in half"], ans:1, exp:"Selection sort: find the minimum of the unsorted portion, swap with the first element of the unsorted portion. After k passes, the first k elements are in their final sorted positions." },
        { q:"String[] words = {'cat', 'dog', 'bird'}; words[1] contains:", opts:["'cat'","'dog'","'bird'","null"], ans:1, exp:"0-indexed: words[0]='cat', words[1]='dog', words[2]='bird'. The SECOND element is at index 1." },
        { q:"An ArrayList grows by automatically when you add more elements than its current capacity by:", opts:["Asking the programmer to resize","Internally creating a larger array and copying all elements — transparent to the programmer","Throwing an exception","Wrapping around to the beginning"], ans:1, exp:"ArrayList dynamic resizing: Java internally manages a backing array. When full, Java creates a new array about 1.5× larger and copies all elements. This is invisible to the programmer — the ArrayList just gets bigger automatically." }
      ])
    ]),
    makeChapter(5,'Recursion & Searching/Sorting',[
      concepts([
        { term:'Recursion', body:'A method that calls itself. Requires: base case (when to stop) + recursive case (call self with modified argument moving toward base case). Stack overflow: too many recursive calls (forgot base case or never reaches it). Trace by hand: draw the call stack.' },
        { term:'Binary Search', body:'Requires SORTED array. Compare target to middle element. If target < middle: search left half. If target > middle: search right half. O(log n) — much faster than linear search O(n) for large datasets. Each comparison halves the search space.' },
        { term:'Sorting Algorithms', body:'Selection sort: O(n²) — find min, swap. Insertion sort: O(n²) — insert each in correct position (efficient for nearly-sorted data). Merge sort: O(n log n) — divide and conquer (split, sort halves, merge). AP CS A FRQs may ask you to trace these.' },
      ]),
      tips(['Recursion: always identify the base case FIRST. Without it, you have infinite recursion.','Binary search requires a sorted array. If asked why binary search doesn\'t work, the array isn\'t sorted.','Merge sort (O(n log n)) is faster than selection/insertion sort (O(n²)) for large data sets.']),
      quiz([
        { q:"What is required for a recursive method to terminate correctly?", opts:["A loop","At least one base case that stops the recursion","A return statement only","The method must call itself exactly once"], ans:1, exp:"Base case: the condition under which the method stops calling itself and returns a direct result. Without a base case (or with a base case that's never reached), recursion continues until a StackOverflowError." },
        { q:"Binary search REQUIRES:", opts:["An ArrayList","A sorted array — it can't work on unsorted data","An array of at least 100 elements","Integer elements only"], ans:1, exp:"Binary search: compare target to middle element, then discard half the array. This only works if the data is sorted — otherwise 'discard the left half' doesn't mean anything." },
        { q:"What is the time complexity of binary search?", opts:["O(n)","O(n²)","O(log n) — each step halves the search space","O(n log n)"], ans:2, exp:"Binary search: O(log n). For an array of 1000 elements, you need at most 10 comparisons (log₂1000 ≈ 10). Compare to linear search: O(n) → up to 1000 comparisons." },
        { q:"In a recursive method, what would happen if the base case is never reached?", opts:["The method returns 0","The method runs forever, eventually causing a StackOverflowError","The method compiles but produces no output","The method throws an ArrayIndexOutOfBoundsException"], ans:1, exp:"Infinite recursion → StackOverflowError: each recursive call adds a frame to the call stack. Without a base case to stop it, the stack fills up (there's a finite limit) and the JVM throws StackOverflowError." },
        { q:"Merge sort uses which algorithmic strategy?", opts:["Greedy","Brute force","Divide and conquer — split the array, recursively sort halves, merge","Dynamic programming"], ans:2, exp:"Merge sort: divide array in half, recursively sort each half, then merge the two sorted halves. O(n log n) time. More complex to implement but far faster than O(n²) sorts for large inputs." },
        { q:"For a binary search on an array of 16 elements, the maximum number of comparisons needed is:", opts:["16","4","8","2"], ans:1, exp:"Binary search: at most log₂(n) + 1 comparisons. log₂(16) = 4. After 4 comparisons, you've narrowed the search to one element. Compare: linear search needs up to 16 comparisons." },
        { q:"What does this recursive method return when called with n=3: public int f(int n) { if (n == 0) return 0; return n + f(n-1); }?", opts:["3","6","9","0"], ans:1, exp:"Trace: f(3) = 3 + f(2) = 3 + 2 + f(1) = 3 + 2 + 1 + f(0) = 3 + 2 + 1 + 0 = 6. This is a recursive summation of integers from 0 to n." },
        { q:"Selection sort is O(n²) because:", opts:["It uses recursion","It always needs two nested loops — the outer loop selects positions, the inner loop finds the minimum","It requires sorted input","It splits the array in half each time"], ans:1, exp:"Selection sort: for each of the n positions (outer loop), scan all remaining n-i elements to find the minimum (inner loop). Total comparisons ≈ n²/2. This is always O(n²) regardless of initial order." },
        { q:"Which sorting algorithm is most efficient for nearly-sorted data?", opts:["Selection sort","Merge sort","Insertion sort — already-sorted or nearly-sorted data requires very few swaps","Binary search"], ans:2, exp:"Insertion sort: best case O(n) for already-sorted data (each element is already in place — just compare once and move on). Worst case O(n²) for reverse-sorted. Natural fit for data that arrives in nearly-sorted order." },
        { q:"A call stack in recursion:", opts:["Stores all array elements","Records each method call — when a base case is reached, results 'unwind' back up the stack","Is the same as a Queue","Only holds one method call at a time"], ans:1, exp:"Call stack: each recursive call adds a frame (local variables, return address). When base case is hit, the bottom frame returns, then the next frame returns its result, etc. — unwinding back to the original call." }
      ])
    ]),
  ]
};

